@js:
(function() {
// 检索分流（参考☁️云端聚合「key 形状分流 + @语法源路由」）：
//   「关键词@源」→ 路由到指定源；「+N 关键词」→ 按 N 模式路由五形态源；两者可叠加。
// 替代旧实现「key 内任意 ≤5 位数字即当 tab」的误伤写法（书名含数字会拿错模式）。
var k = String(key || '');
var tag = '';
var m = k.match(/^(.*?)[@＠]\s*([^\s@＠]+)\s*$/);
if (m && m[1]) { k = m[1].replace(/\s+$/, ''); tag = m[2]; }
var tab = '';
var p = k.match(/^\+\s*(\d{1,2})\b\s*/);
if (p) { tab = p[1]; k = k.slice(p[0].length); }
if (!k) k = String(key || '');
return LP_SEARCH_URL(k, page, tab, tag);
})();

