// ===== 工具函数 =====
function GET(k) {
  const { java, source } = this;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  return d[k] || '';
}

function SET(k, v) {
  const { java, source } = this;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  d[k] = v;
  source.putVariable(JSON.stringify(d, null, '\t'));
}


// ===== 网关鉴权（LoomProxy api_key，登录面板「apikey」输入框录入 → 源变量）=====
// 不内嵌默认 key：未填写时请求不带凭证，由网关返回 401 提示
function LP_KEY() {
  return GET.call(this, 'apikey') || '';
}

// 「网关地址」控件的不可见版本键：名字尾部按 gw_key_ver 追加零宽空格（U+200B），
// 显示不变但 loginInfoMap 键变化——setHost 递增版本后，旧键条目作废、
// 控件重绘取新 default（=当前 host），不依赖面板上下文对 map 的写能力。
function LP_GW_NAME() {
  var v = 0;
  try { v = Number(GET.call(this, 'gw_key_ver') || '0') || 0; } catch (eV) {}
  var n = '网关地址';
  for (var i = 0; i < v; i++) n += '​';
  return n;
}

function withKey(url) {
  var k = LP_KEY.call(this);
  if (!k) return url;
  return url + (url.indexOf('?') >= 0 ? '&' : '?') + 'api_key=' + k;
}
// ===== 发现页数据 =====
// 平台公告
function getAnn() {
  const {java, cache, source} = this;
  // 公告拉取失败不应中断发现页渲染
  try {
    let url = GET.call(this, 'host') + '/announcement';
    let con = cache.get('announcement');
    let resp = JSON.parse(java.ajax(withKey.call(this, url))).data.content;
    if (con && con == resp) return;
    cache.put('announcement', resp);

    if (/书源更新/.test(resp)) {
      SET.call(this, 'updateSource', 1);
    }

    java.longToast('\n平台公告：' + resp);
  } catch (e) { java.log('getAnn: ' + e); }
}

// ===== 数据源注册表 =====
// 注册表唯一来源=网关 /datasources（2026-11-06 先生令「不用内置兜底快照」）：
//   · getOrigins() 先拉 {host}/datasources，6h TTL 缓存；拉取失败/离线 → 缓存副本，无副本即空表；
//   · 登录页/面板/检索扇出走只读口 getOriginsLocal()（缓存副本→空表，永不 java.ajax）。
//   · 未内置静态快照：形态 tab 与发现页渲染键以网关下发为准，本地不再覆盖。

var LP_ORIGINS_LOCAL = [];

// 注册表合并：本地快照定「顺序/形态 tab/发现渲染键」，网关注册表定「有哪些源（在册者才留）」
// 并补充名称/媒介。顺序按本地快照（策划的 UI 顺序，番茄系在前），网关新收录、本地未登记的源
// 按网关顺序追加（默认 tab，files 空=只搜索）。这样下线源自动消失、新源自动出现，面板顺序不漂。
function LP_ONE_ORIGIN(loc, g) {
  var tabs = (loc && loc.search_tab && loc.search_tab.length) ? loc.search_tab
    : (g.search_tab && g.search_tab.length ? g.search_tab : [{ tab_type: 3, name: '小说' }]);
  var nt = [];
  for (var k = 0; k < tabs.length; k++) nt.push({ tab_type: tabs[k].tab_type, name: tabs[k].name });
  return {
    id: g.id,
    name: g.name || (loc && loc.name) || g.id,
    category: g.category || (loc && loc.category) || '',
    media: g.media_type || (loc && loc.media) || '',
    // 源站分类（网关注册表下发的纯视图字段，下游可选依赖）：面板据此分组；
    // 本地快照不带 group（网关管理员视图，会漂移），故离线兜底由面板按 media 兜底。
    group_id: g.group_id || (loc && loc.group_id) || 0,
    group: g.group || (loc && loc.group) || '',
    search_tab: nt,
    files: (loc && loc.files) ? loc.files : []
  };
}

function LP_MERGE_ORIGINS(gw) {
  var byId = {};
  for (var i = 0; i < gw.length; i++) { if (gw[i] && gw[i].id) byId[gw[i].id] = gw[i]; }
  var out = [], seen = {};
  for (var j = 0; j < LP_ORIGINS_LOCAL.length; j++) {
    var loc = LP_ORIGINS_LOCAL[j];
    var g = byId[loc.id];
    if (!g) continue;              // 网关未在册（下线）→ 丢弃
    seen[loc.id] = 1;
    out.push(LP_ONE_ORIGIN(loc, g));
  }
  for (var m = 0; m < gw.length; m++) {
    var g2 = gw[m];
    if (!g2 || !g2.id || seen[g2.id]) continue;
    out.push(LP_ONE_ORIGIN(null, g2));   // 网关新收录、本地未登记的源
  }
  return out;
}

// ===== 数据源注册表取数层 =====
// 缓存键 syiism_origins 存 {t:拉取时刻, list:合并后清单}。两条读径分工明确：
//   · getOrigins()      —— 发现页等「用户已在等网络」的动作路径：6h TTL 内用缓存，过期强拉，
//                          失败回退旧副本再回内置快照（顺带把缓存预热，供只读口取用）。
//   · getOriginsLocal() —— 登录页渲染 / 面板渲染 / 检索扇出：只读「缓存副本→内置快照」，
//                          永不 java.ajax。旧实现登录页冷缓存渲染要连撞 4 次 /datasources
//                          （LP_INIT + 三处按钮网格/清单），失败又不写缓存 → 网关不可达时
//                          每次都是整串同步超时（实测对照见 README v3.2.0）。
// 新源/下线源只有经 getOrigins() 或「🔄 刷新源站」拉过一次才在只读口浮现。
var LP_ORIGINS_TTL = 6 * 60 * 60 * 1000;

// 读缓存副本 → {t,list}；无缓存/解析失败/cache 取不到（上下文无 bindings）一律返回 null。
function LP_CACHE_READ() {
  var C = (this && this.cache) || null;
  if (!C) return null;
  var o = null;
  try { o = JSON.parse(C.get('syiism_origins') || 'null'); } catch (e0) { o = null; }
  return (o && o.list && o.list.length) ? o : null;
}

// 只读口（零网络）：缓存副本不论新鲜度，取不到就内置快照。
function getOriginsLocal() {
  var c = LP_CACHE_READ.call(this);
  return (c && c.list) ? c.list : LP_ORIGINS_LOCAL;
}

// 网络口：拉 /datasources → LP_MERGE_ORIGINS 合并快照 → 回写缓存。任一环失败返回 null。
function LP_FETCH_MERGE() {
  var host = '';
  try { host = String(GET.call(this, 'host') || ''); } catch (eH) {}
  if (!/^https?:\/\//.test(host)) return null;
  try {
    var resp = JSON.parse(String(this.java.ajax(withKey.call(this, host + '/datasources'))));
    var arr = resp && resp.data;
    if (!arr || !arr.length) return null;
    var merged = LP_MERGE_ORIGINS(arr);
    if (!merged.length) return null;
    var C = (this && this.cache) || null;
    if (C) { try { C.put('syiism_origins', JSON.stringify({ t: Date.now(), list: merged })); } catch (eP) {} }
    return merged;
  } catch (eF) { return null; }
}

function getOrigins() {
  var c = LP_CACHE_READ.call(this);
  if (c && (Date.now() - (c.t || 0) < LP_ORIGINS_TTL)) return c.list;
  var merged = LP_FETCH_MERGE.call(this);
  if (merged) return merged;
  return c ? c.list : LP_ORIGINS_LOCAL;
}

// 清单来源说明（面板副标题用）：缓存副本 →「缓存 N 源 · 更新于 …」，否则「内置快照（离线）」
// ——让「没点刷新看不到新源」这件事肉眼可见。
function LP_ORIGIN_SRC_TEXT() {
  var c = LP_CACHE_READ.call(this);
  if (!c) return '尚未拉到注册表（离线，点登录页「🔄 刷新源站」取最新）';
  var d = new Date(c.t || 0);
  var p = function (x) { return (x < 10 ? '0' : '') + x; };
  return '缓存 ' + c.list.length + ' 源 · 更新于 ' + p(d.getMonth() + 1) + '-' + p(d.getDate())
    + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
}

// 登录页「🔄 刷新源站」：显式绕过 TTL 强拉一次并回写缓存。当前主站若已被网关下线，
// 不在这里处理——reLoginView 重放 loginUi 时 LP_INIT 会读着新缓存自动迁回默认源。
function lpRefreshOrigins() {
  var J = (this && this.java) || null;
  var before = LP_CACHE_READ.call(this);
  var merged = LP_FETCH_MERGE.call(this);
  if (!merged) {
    if (J) try {
      J.longToast('\n🔄 刷新源站失败：网关不可达或未下发清单\n沿用 ' + LP_ORIGIN_SRC_TEXT.call(this));
    } catch (eT0) {}
    return;
  }
  var delta = (before && before.list) ? merged.length - before.list.length : 0;
  var msg = '\n🔄 源站清单已刷新：' + merged.length + ' 源'
    + (delta > 0 ? '（新增 ' + delta + '）' : (delta < 0 ? '（下线 ' + (-delta) + '）' : ''));
  if (!LP_CACHE_READ.call(this)) msg += '\n⚠️ 缓存通道不可用，本次结果不持久（下次渲染回退内置快照）';
  if (J) {
    try { J.longToast(msg); } catch (eT1) {}
    try { J.reLoginView(); } catch (eR) {}
  }
}

// 发现页 category 编码：编码 ? & = 等分隔符，但保留 /（网关按首段切 kind，路径里的斜杠要留）。
function lpEnc(s) { return encodeURIComponent(String(s)).replace(/%2F/gi, '/'); }

// 按源 id 取媒介（novel/audio/comic/video）。详情 DTO 的 bookType/bookTypeCode 对新源为空
// （code=0 的零值），intro.js 据此把媒介落定给 Legado 的 book.type——本地快照优先（零请求），
// 未收录再查动态注册表；都没有返回空串。
function LP_MEDIA_OF(id) {
  var s = String(id || '');
  if (!s) return '';
  for (var i = 0; i < LP_ORIGINS_LOCAL.length; i++) {
    if (LP_ORIGINS_LOCAL[i].id == s) return LP_ORIGINS_LOCAL[i].media || '';
  }
  var os = [];
  try { os = getOriginsLocal.call(this) || []; } catch (e) {}
  for (var j = 0; j < os.length; j++) if (os[j].id == s) return os[j].media || '';
  return '';
}

// 番茄朗读/听书音色表（tone_id 纯数字字符串；移植自 fq-hg-mini shell.js TONES）。
// 面板音色菜单据此渲染按钮，tone_id 经 ruleToc chapterUrl 的 toneId 透传给朗读正文接口。
var LP_TONES = [
  ['默认', '1'], ['真人', '0'], ['甜美少女', '1'], ['清亮青叔', '2'], ['成熟大叔', '4'],
  ['开朗青年', '5'], ['温柔淑女', '6'], ['风雅青叔', '8'], ['清纯少女', '12'], ['磁性青叔', '17'],
  ['推文女声', '27'], ['亲切姐姐', '28'], ['儒雅大叔', '29'], ['优雅御姐', '30'], ['斯文青叔', '31'],
  ['知性主播', '32'], ['多人对话', '51'], ['成熟升级', '74'], ['俏皮御姐', '100'], ['双音灵动', '103'],
  ['王明军音', '105']
];

// 分类数据获取：静态字典构建期内嵌进 LP_DATA（运行时零请求），未内嵌的
// 键走 CacheManager 缓存层（先本地后网络，失败回退，仅"无缓存且失败"抛错）。
function getCateData(name, force) {
  const { java, cache } = this;
  var category = GET.call(this, 'category');
  var embedded = (typeof LP_DATA !== 'undefined') && (LP_DATA[name] || LP_DATA[category + '_' + name]);
  if (embedded) return embedded;
  var key = 'syiism_cate_' + category + '_' + name;
  var cached = '';
  try { cached = cache.get(key) || ''; } catch (e) {}
  if (force || !cached) {
    try {
      var url = GET.call(this, 'host') + '/data/' + category + '/' + name + '.json';
      var data = JSON.parse(java.ajax(withKey.call(this, url)));
      try { cache.put(key, JSON.stringify(data)); } catch (e) {}
      return data;
    } catch (e) { java.log('getCateData ' + name + ': ' + e); }
  }
  if (cached) return JSON.parse(cached);
  throw new Error('分类数据 ' + name + ' 拉取失败且无本地缓存');
}

// 初始化源变量（默认生产网关 + 番茄小说模式）。原在 loginUrl/exploreUrl
// 各写一份，现收进 jsLib：jsLib 词法上无 source/java 绑定，须从 this 解构
// 首用兜底：装源后未打开过发现/登录页就直接搜索时，补齐必要源变量默认值。
// 只填缺失键、不覆盖已有值；已下线数据源（fq_hg 等）自动迁移到默认源并
// 同步刷新 host——否则旧变量会让 loginUi 的 searchTabs[origin] 崩溃成死锁。
function LP_INIT() {
  var defs = {
    host: 'https://loomproxy.dpdns.org',
    origin: 'fq_novel',
    origin_zh: '番茄小说',
    category: 'fq',
    tab_type: 3,
    tone_id: '0',
    module: '小说'
  };
  var d = {};
  try { d = JSON.parse(this.source.getVariable() || '{}') || {}; } catch (e) { d = {}; }
  var changed = false;
  for (var k in defs) { if (!d[k]) { d[k] = defs[k]; changed = true; } }
  var ids = getOriginsLocal.call(this).map(function (x) { return x.id; });
  if (d.origin && ids.indexOf(d.origin) < 0) {
    d.origin = defs.origin; d.origin_zh = defs.origin_zh; d.category = defs.category;
    d.tab_type = defs.tab_type; d.module = defs.module;
    d.originIdx = 0; d.host = defs.host;
    changed = true;
  }
  if (changed) { try { this.source.setVariable(JSON.stringify(d, null, '\t')); } catch (e2) {} }
}

