// @源 解析：id 精确 → 全名精确 → 去括号名精确 → 别名表 → 名称包含；失败返回 null
function LP_RESOLVE_ORIGIN(tag) {
  var t = String(tag || '').trim().toLowerCase();
  if (!t) return null;
  var os = getOriginsLocal.call(this);
  var i;
  for (i = 0; i < os.length; i++) if (os[i].id == t) return os[i];
  for (i = 0; i < os.length; i++) if (os[i].name.toLowerCase() == t) return os[i];
  for (i = 0; i < os.length; i++) if (os[i].name.replace(/[（(].*$/, '').toLowerCase() == t) return os[i];
  var aid = LP_ALIAS[t];
  if (aid) for (i = 0; i < os.length; i++) if (os[i].id == aid) return os[i];
  for (i = 0; i < os.length; i++) if (os[i].name.toLowerCase().indexOf(t) >= 0) return os[i];
  return null;
}

// 切源落定（tab 取本源 search_tab[0]）——登录页「📡 源站自定义」面板选主站、检索 @源 路由、
// +N 前缀切形态源三条入口共用这一份，别再另写同构实现。
function LP_APPLY_ORIGIN(o) {
  var os = getOriginsLocal.call(this);
  for (var i = 0; i < os.length; i++) {
    if (os[i].id != o.id) continue;
    SET.call(this, 'originIdx', i);
    break;
  }
  SET.call(this, 'origin', o.id);
  SET.call(this, 'origin_zh', o.name);
  SET.call(this, 'category', o.category);
  var tab = (o.search_tab && o.search_tab[0]) || { tab_type: 3, name: '小说' };
  SET.call(this, 'tab_type', tab.tab_type);
  SET.call(this, 'module', tab.name);
}

// 数据源中文别名：结果项的 source 字段（网关下发的源码，如 fq_novel）→ 注册表 name。
// 聚合检索的结果可能来自多个源，故按结果项自身 source 取名，而不是当前源变量 origin；
// 结果项没有 source 才回退当前源。未注册的源码原样返回，两头都取不到给空串。
function LP_SRC_ZH(item) {
  var id = '';
  try {
    var d = typeof item == 'string' ? JSON.parse(item) : (item || {});
    id = String(d.source || '');
  } catch (e) {}
  if (!id) { try { id = String(GET.call(this, 'origin') || ''); } catch (e2) {} }
  if (!id) return '';
  var o = null;
  try { o = LP_RESOLVE_ORIGIN.call(this, id); } catch (e3) {}
  return o ? o.name : id;
}

// 聚合范围（登录面板可自定义）：源变量 agg_srcs——
//   未设置（''）= 全部注册源（历史默认）；'none' = 只搜当前源（不扇出）；
//   其余为逗号分隔的参与源 id（存储无序，装配时按注册表顺序过滤）。
// 走只读口：检索扇出不该为「拿清单」多花一次网络往返，清单新鲜度由「🔄 刷新源站」保证。
function lpAggSrcList() {
  var all = [];
  getOriginsLocal.call(this).forEach(function (x) { all.push(x.id); });
  var raw = String(GET.call(this, 'agg_srcs') || '');
  if (raw == 'none') return [];
  if (!raw) return all;
  var keep = {};
  raw.split(',').forEach(function (s) { if (s) keep[s.trim()] = 1; });
  return all.filter(function (id) { return keep[id]; });
}

// 聚合扇出（网关 /app/aggregate_search.go 契约）：search 带 sources=码1,码2… 时多源
// 合并返回、每条结果盖 source 标（bookUrl 模板 `$.source || GET('origin')` 据此路由回源）。
// 入口源由网关自动置顶去重、总数截 LP_AGG_LIMIT——书源侧按范围列 最多 LP_AGG_LIMIT-1 个（入口外），
// 自截不靠网关裁尾。上限随网关调整（v3.1.0 由 8 提到 32）。
var LP_AGG_LIMIT = 32;
function LP_AGG_SUFFIX(excludeId) {
  if (String(GET.call(this, 'agg_search')) != '1') return '';
  var sel = lpAggSrcList.call(this).filter(function (id) { return id != excludeId; });
  sel = sel.slice(0, LP_AGG_LIMIT - 1);
  return sel.length ? ('&sources=' + sel.join(',')) : '';
}

function LP_SEARCH_URL(key, page, tabOverride, originTag) {
  LP_INIT.call(this);
  // jsLib 词法无 java 绑定（见 10-util 注释），统一从 this 取
  var J = (this && this.java) || null;
  var o = GET.call(this, 'origin');
  if (originTag) {
    var ro = LP_RESOLVE_ORIGIN.call(this, originTag);
    if (ro) {
      if (ro.id != o) {
        LP_APPLY_ORIGIN.call(this, ro);
        if (J) try { J.toast('\n🔀 本次检索路由到: ' + ro.name); } catch (eT) {}
      }
      o = ro.id;
      if (o == 'xmly') {
        return withKey.call(this, GET.call(this, 'host') + '/xmly/search?query=' + key) + LP_AGG_SUFFIX.call(this, o);
      }
    } else {
      if (J) try { J.toast('\n未识别的源「' + originTag + '」，按当前源检索'); } catch (eU) {}
    }
  }
  if (o == 'xmly') {
    return withKey.call(this, GET.call(this, 'host') + '/xmly/search?query=' + key) + LP_AGG_SUFFIX.call(this, o);
  }
  if (LP_FORM_IDS.indexOf(o) >= 0) {
    var ov = String(tabOverride === undefined || tabOverride === null ? '' : tabOverride);
    if (ov && LP_TAB2ID[ov]) {
      var mapped = LP_TAB2ID[ov];
      if (mapped != o) {
        // 前缀切源同样要落定变量（原实现只改 URL 不落定，bookUrl 挂旧通道的缺陷修复）
        var mos = getOriginsLocal.call(this);
        var mname = mapped;
        for (var mi = 0; mi < mos.length; mi++) {
          if (mos[mi].id == mapped) { LP_APPLY_ORIGIN.call(this, mos[mi]); mname = mos[mi].name; break; }
        }
        if (J) try { J.toast('\n🔀 本次检索路由到: ' + mname); } catch (eM) {}
        o = mapped;
      }
    }
  }
  var tail = '';
  if (o == 'wd_novel') {
    // 微点搜索按站点分流：1=男生 2=女生（面板站点按钮落定 tab_type）
    tail = '&tabType=' + encodeURIComponent(String(GET.call(this, 'tab_type') || '1'));
  }
  return withKey.call(this, GET.call(this, 'host') + '/' + o + '/search?query=' + key + '&page=' + (page || 1) + tail) + LP_AGG_SUFFIX.call(this, o);
}

// ===== 排行榜（网关 /rank/boards，天数由登录面板切换 1/7/30，默认 7）=====
// 数据形如 {code,data:{boards:[{dim:'keyword'|'book',title,unit,rows:[{name,total,book_id?}]}]}}。
// 鉴权走阅读端登录网关面板后的 cookie（cookieJar 携带 JWT），api_key 为 withKey 兜底参数；
// 401 时回退缓存、再失败交由调用方降级渲染，不阻断发现页。缓存键按 源+天数 区分。
var LP_RANK_DAY_OK = ['1', '7', '30'];
function LP_RANK_DAYS() {
  var d = String(GET.call(this, 'rank_days') || '7');
  return LP_RANK_DAY_OK.indexOf(d) >= 0 ? d : '7';
}

function LP_RANK(force) {
  var java = this.java, cache = this.cache;
  var origin = GET.call(this, 'origin');
  var days = LP_RANK_DAYS.call(this);
  var ckey = 'syiism_rank_' + origin + '_' + days;
  if (force != 1) {
    try { var c = cache.get(ckey); if (c) return JSON.parse(c); } catch (eC) {}
  }
  var url = withKey.call(this, GET.call(this, 'host') + '/rank/boards?days=' + days + '&source=' + origin);
  var resp = null;
  try { resp = JSON.parse(String(java.ajax(url))); } catch (eA) { resp = null; }
  var bd = resp && (resp.boards || (resp.data && resp.data.boards));
  if (!bd) {
    var m = resp && resp.msg ? String(resp.msg) : '榜单拉取失败';
    var cached = '';
    try { cached = cache.get(ckey) || ''; } catch (e2) {}
    if (cached) return JSON.parse(cached);
    throw new Error(m);
  }
  var data = (resp.data && resp.data.boards) ? resp.data : { boards: bd };
  try { cache.put(ckey, JSON.stringify(data)); } catch (e3) {}
  return data;
}

// 发现页搜索热词按钮 → 打开搜索界面（rrssk 同款 java.searchBook）
function lpSearchBoard(word) {
  var J = this.java, S = this.source;
  try { J.searchBook(String(word || ''), S); }
  catch (e) { try { J.toast('打开搜索失败: ' + e); } catch (e2) {} }
}

// ===== 网关服务器池（参考☁️云端聚合「服务器切换/服务器检测」）=====
// 池 = 当前 host（若在池外视为自定义优先）+ 生产网关；探测走免鉴权 /announcement
// （{"code":0,...,"msg":"ok"}），选首个可达者落定。
// 本地联调网关**不进池**：那是开发机局域网地址，会随网络漂移，也不该写进公开产物——
// 联调时在面板「网关地址」框手填，它作为「自定义优先」自然参与探测。
function LP_HOSTS() {
  var cur = String(GET.call(this, 'host') || '').replace(/\/+$/, '');
  var pool = ['https://loomproxy.dpdns.org'];
  var out = [];
  if (/^https?:\/\//.test(cur)) out.push(cur);
  for (var i = 0; i < pool.length; i++) if (out.indexOf(pool[i]) < 0) out.push(pool[i]);
  return out;
}

function lpCheckHosts() {
  var java = this.java;
  var list = LP_HOSTS.call(this);
  var first = '';
  var lines = [];
  for (var i = 0; i < list.length; i++) {
    var h = list[i];
    var good = false;
    try {
      good = /"msg"\s*:\s*"ok"/.test(String(java.ajax(h + '/announcement') || ''));
    } catch (e) { good = false; }
    lines.push((good ? '✅ ' : '❌ ') + h);
    if (good && !first) first = h;
  }
  if (first) {
    if (first != GET.call(this, 'host')) {
      SET.call(this, 'host', first);
      java.longToast('\n🔍 网关检测：\n' + lines.join('\n') + '\n→ 已切换到 ' + first);
    } else {
      java.longToast('\n🔍 网关检测：\n' + lines.join('\n') + '\n当前网关正常');
    }
  } else {
    java.longToast('\n🔍 网关检测：全部不可达\n' + lines.join('\n'));
  }
  try { java.reLoginView(); } catch (eR) {}
}
