// 播放页选集切换桥：按 itemId 重取视频流，返回 JSON 字符串（WebView 内 run() 调用）
function fqVideoStreamJson(itemId, origin, tabType, bookId) {
  try {
    var host = GET.call(this, 'host');
    var key = LP_KEY.call(this);
    var o = origin || GET.call(this, 'origin');
    var t = tabType || GET.call(this, 'tab_type');
    var b = bookId || GET.call(this, 'bookId');
    var url = host + '/' + o + '/content?bookId=' + b + '&tabType=' + t +
      '&toneId=' + (GET.call(this, 'tone_id') || '0') + '&itemId=' + itemId;
    if (key) url += '&api_key=' + key;
    var d = JSON.parse(this.java.ajax(url));
    var data = (d && d.data) || {};
    if (d && d.contentType === 'video' && data.content) {
      return JSON.stringify({ url: data.content, keyHex: data.keyHex || '', size: Number(data.size) || 0 });
    }
    return JSON.stringify({ err: (data && data.message) || (d && d.msg) || '视频流解析失败' });
  } catch (e) {
    return JSON.stringify({ err: String(e && e.message || e) });
  }
}

function fqCencPlayerHtml(title, url, keyHex, size, episodes, curIdx, site, tab, bookId, initRate) {
