            tmp.push({ id: String(epList[ei].id || ''), t: String(epList[ei].t || ('第' + (ei + 1) + '集')) });
        }
        epJson = JSON.stringify(tmp);
    } catch (e0) { epJson = '[]'; }
    epJson = epJson.replace(/</g, '\\u003c');

    // ---- 页面脚本（解密核心与原始真机可播实现保持一致）----
