        + "var LB=document.getElementById('lockBtn'),IL=document.getElementById('icLock'),IU=document.getElementById('icUnlock'),ICP=document.getElementById('icPlay'),ICQ=document.getElementById('icPause');"
        + "function msg(t,f){var n=Date.now();if(!f&&n-T<250)return;T=n;t=String(t||'');"
