        + "function u16(a,p){return(a[p]<<8)|a[p+1];}"
        + "function u32(a,p){return a[p]*16777216+a[p+1]*65536+a[p+2]*256+a[p+3];}"
        + "function u64(a,p){return u32(a,p)*4294967296+u32(a,p+4);}"
