// ===== 内置 HTML 面板（参考☁️云端聚合 SourceSelector：data-URI + startBrowserAwait）=====
// 分工与云端一致：数据（源站清单 / 版本日志）先在 Legado JS 侧取好、烘进 HTML；WebView 只做
// 交互，产出经隐藏 <div id="xxx-output"> 回传，Legado 侧正则解析后写源变量。一个面板可以有多
// 个 output div，各自独立正则、独立落键（缺一个产出不能把另一个一起吞掉）。
//   · lpSourceSelector()      源站自定义——卡片上半单选当前主站（#origin-output → LP_APPLY_ORIGIN）
//                             + 下半多选参与聚合的源站（#agg-output → agg_srcs）；
//                             清单走只读口 getOriginsLocal()，开面板不发网络。
//   · lpUpdatePanel(localVer) 书源更新——渲染网关 version.json 的更新日志 + 一键导入书源
// 分类渲染「用站点下发的源站分类」：优先 group（网关注册表视图字段），缺失按 media_type 兜底。

var LP_MEDIA_LABEL = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
var LP_MEDIA_ORDER = ['novel', 'audio', 'comic', 'video'];

// 源站分组标签：group 优先（网关下发），media_type 兜底，都无 → 其他
function LP_GROUP_LABEL(o) {
  if (o && o.group) return String(o.group);
  return LP_MEDIA_LABEL[o && o.media] || '其他';
}

// 按源站分类聚合：组序 = 组内最小 group_id（网关注册表下发）升序，缺失用 media 序 1000+ 兜底。
// 同标签的源（如 group=小说 与 media=novel）并入同组，不重复出 tab。
function LP_ORIGIN_GROUPS(os) {
  var groups = [], idx = {};
  for (var i = 0; i < os.length; i++) {
    var o = os[i], lb = LP_GROUP_LABEL(o);
    if (!(lb in idx)) { idx[lb] = groups.length; groups.push({ label: lb, items: [], key: 1e9 }); }
    var g = groups[idx[lb]];
    g.items.push(o);
    var mi = LP_MEDIA_ORDER.indexOf(o.media); if (mi < 0) mi = 9;
    var key = (o.group_id && o.group_id > 0) ? o.group_id : (1000 + mi);
    if (key < g.key) g.key = key;
  }
  groups.sort(function (a, b) { return a.key - b.key; });
  return groups;
}

