  var script = 'var ORDER=' + JSON.stringify(order) + ';var TOTAL=' + os.length
    + ';var NAMES=' + JSON.stringify(names) + ';'
    + 'function switchTab(i){document.querySelectorAll(".tab").forEach(function(b){b.classList.toggle("active",b.getAttribute("data-tab")===String(i));});document.querySelectorAll(".panel").forEach(function(p){p.classList.toggle("active",p.id==="panel-"+i);});}'
    + 'function ocards(g){var a=[];document.querySelectorAll(".ocard").forEach(function(c){if(g===null||c.getAttribute("data-group")===String(g))a.push(c);});return a;}'
    + 'function pickMain(el){document.querySelectorAll(".card.main").forEach(function(c){c.classList.remove("main");});el.classList.add("main");updateOutput();}'
    + 'function pickAgg(el){el.classList.toggle("on");var g=el.parentNode.getAttribute("data-group");var cs=ocards(g),on=cs.length>0;for(var i=0;i<cs.length;i++){var a=cs[i].querySelector(".cagg");if(!a||!a.classList.contains("on"))on=false;}document.querySelectorAll(".card.all").forEach(function(x){if(x.getAttribute("data-group")===String(g))x.classList.toggle("selected",on);});updateOutput();}'
    + 'function pickGroup(el){var g=el.getAttribute("data-group");var on=!el.classList.contains("selected");el.classList.toggle("selected",on);ocards(g).forEach(function(c){var a=c.querySelector(".cagg");if(a)a.classList.toggle("on",on);});updateOutput();}'
    + 'function pickAll(){ocards(null).forEach(function(c){var a=c.querySelector(".cagg");if(a)a.classList.add("on");});document.querySelectorAll(".card.all").forEach(function(x){x.classList.add("selected");});updateOutput();}'
    + 'function clearAll(){ocards(null).forEach(function(c){var a=c.querySelector(".cagg");if(a)a.classList.remove("on");});document.querySelectorAll(".card.all").forEach(function(x){x.classList.remove("selected");});updateOutput();}'
    + 'function updateOutput(){var sel=[];ocards(null).forEach(function(c){var a=c.querySelector(".cagg");if(a&&a.classList.contains("on"))sel.push(c.getAttribute("data-id"));});var ordered=ORDER.filter(function(id){return sel.indexOf(id)>=0;});document.getElementById("agg-output").textContent=ordered.length===0?"__NONE__":(ordered.length===TOTAL?"__ALL__":ordered.join(","));var m=document.querySelector(".card.main");if(m)document.getElementById("origin-output").textContent=m.getAttribute("data-id");var nm=m?NAMES[m.getAttribute("data-id")]:"";document.getElementById("bar").textContent="主站 "+(nm||"(不在册)")+" · 已选 "+ordered.length+" / "+TOTAL;}';

  var srcText = '';
  try { srcText = String(LP_ORIGIN_SRC_TEXT.call(this) || ''); } catch (eSrc) {}
  var curName = names[curOrigin] || '';
  // 隐藏 div 用 `[^<]*` 正则取值，产出只允许 id 字符集（注册表 id 均为 [0-9A-Za-z_-]）
  var outOrigin = String(curOrigin).replace(/[^0-9A-Za-z_\-]/g, '');

  var html = '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">'
    + '<title>源站自定义</title><style>' + LP_PANEL_CSS + '</style></head><body><div class="wrap">'
    + '<h1>📡 源站自定义</h1>'
    + '<div class="sub"><b>点卡片上半＝设为当前主站</b>（单选，检索/发现随之切换）；'
    + '<b>点下半「参与聚合」＝勾选参与聚合搜索的源站</b>（网关上限 ' + LP_AGG_LIMIT + ' 源，含入口）。'
    + '分类来自网关下发的源站分组，<b>改完返回本页即保存</b>。'
    + '<br>清单：' + (srcText || (os.length + ' 源')) + '｜当前主站：' + (curName || (outOrigin + '（不在册）')) + '</div>'
    + '<div class="tabs">' + tabsHtml + '</div>'
    + panelsHtml
    + '<div class="foot"><button class="ghost" onclick="clearAll()">清空聚合</button><button onclick="pickAll()">全选聚合</button></div>'
    + '<div class="bar" id="bar">主站 ' + (curName || '(不在册)') + ' · 已选 ' + curList.length + ' / ' + os.length + '</div>'
    + '<div id="agg-output" style="display:none;">' + initOut + '</div>'
    + '<div id="origin-output" style="display:none;">' + outOrigin + '</div>'
    + '</div><script>' + script + '</script></body></html>';

  var result = null;
  try { result = J.startBrowserAwait('data:text/html;base64,' + J.base64Encode(html), '源站自定义', false); } catch (e4) { result = null; }
  if (!result || !result.body()) { if (J) { try { J.toast('\n已取消源站设置'); } catch (e5) {} } return; }
  var bodyTxt = '';
  try { bodyTxt = String(result.body()); } catch (eB) { bodyTxt = ''; }
  var done = [];

  // 聚合通道：无产出（空串）就不动 agg_srcs——原实现 `if (raw === '') return` 会把主站通道一起吞掉
  var ma = bodyTxt.match(/<div id="agg-output"[^>]*>([^<]*)<\/div>/);
  var raw = (ma && ma[1]) ? ma[1].trim() : '';
  if (raw !== '') {
    if (raw === '__ALL__') SET.call(this, 'agg_srcs', '');
    else if (raw === '__NONE__') SET.call(this, 'agg_srcs', 'none');
    else SET.call(this, 'agg_srcs', raw);
    var n = raw === '__ALL__' ? os.length : (raw === '__NONE__' ? 0 : raw.split(',').length);
    done.push('聚合 ' + n + '/' + os.length + ' 源');
  }

  // 主站通道：与源变量不同才切（切法复用 LP_APPLY_ORIGIN——tab_type 取本源 search_tab[0]）；
  // 解析不到（已下线/非法 id）只提示不写，别替用户静默改源
  var mo = bodyTxt.match(/<div id="origin-output"[^>]*>([^<]*)<\/div>/);
  var oid = (mo && mo[1]) ? mo[1].trim() : '';
  if (oid && oid !== curOrigin) {
    var picked = null;
    try { picked = LP_RESOLVE_ORIGIN.call(this, oid); } catch (eR) { picked = null; }
    if (picked) { LP_APPLY_ORIGIN.call(this, picked); done.push('主站 ' + picked.name); }
    else done.push('主站「' + oid + '」不在册，未切换');
  }

  if (!J) return;
  try { J.toast('\n📡 源站自定义：' + (done.length ? done.join(' ｜ ') : '未改动')); } catch (e6) {}
  try { J.reLoginView(); } catch (e7) {}   // 刷新登录页入口按钮上的主站名与参与数
}

// ===== 书源更新面板（复刻云端 version() 面板形态，日志走 version.json）=====
// 数据来自网关静态托管 /data/shuyuan/version.json（更新日志）与 bookSource.json（书源直链）。
// 一键更新走 WebView 的 legado:// 拦截（WebViewActivity.shouldOverrideUrlLoading）。
function lpUpdatePanel(localVer) {
  var J = (this && this.java) || null;
  var S = (this && this.source) || null;
  var host = '';
  try { host = String(GET.call(this, 'host') || '').replace(/\/+$/, ''); } catch (e0) {}
  if (!/^https?:\/\//.test(host)) { if (J) { try { J.toast('\n网关地址未设置或不合法'); } catch (e1) {} } return; }
  var verUrl = host + '/data/shuyuan/version.json';
  var srcUrl = host + '/data/shuyuan/bookSource.json';
  var remote = null;
  try { remote = JSON.parse(String(J.ajax(verUrl))); } catch (e2) { remote = null; }
  var latest = (remote && remote.latesVer) ? String(remote.latesVer) : '';
  var log = (remote && remote.log) ? remote.log : null;
  var history = (remote && remote.history && remote.history.length) ? remote.history : [];
  var lv = String(localVer || '');

  function cmp(a, b) {
    var x = String(a || '').split('.'), y = String(b || '').split('.');
    var n = Math.max(x.length, y.length);
    for (var i = 0; i < n; i++) {
      var p = Number(x[i] || 0), q = Number(y[i] || 0);
      if (p > q) return 1; if (p < q) return -1;
    }
    return 0;
  }
  var cls = 'err', msg = '未能获取线上版本信息（' + verUrl + '）';
  if (latest) {
    var d = cmp(lv, latest);
    if (d < 0) { cls = 'new'; msg = '发现新版本 v' + lv + ' → v' + latest + '，点下方按钮一键更新'; }
    else if (d === 0) { cls = 'ok'; msg = '当前已是最新版本 v' + latest; }
    else { cls = 'ok'; msg = '当前版本 v' + lv + ' 高于线上 v' + latest; }
  }

  var logText = log ? ('【更新日期：' + (log.date || '') + '】\n' + (log.content || '')) : '（无更新日志）';
  var histHtml = '';
  for (var hi = 0; hi < history.length; hi++) {
    histHtml += '<div class="h"><b>' + (history[hi].date || '') + '</b>' + (history[hi].content || '') + '</div>';
  }

  var html = '<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">'
    + '<title>书源更新</title><style>' + LP_PANEL_CSS + '</style></head><body><div class="wrap">'
    + '<h1>🔄 书源更新</h1>'
    + '<div class="sub">' + ((S && S.bookSourceName) || 'syiism聚合') + ' · 分组 ' + ((S && S.bookSourceGroup) || '') + '</div>'
    + '<div class="banner ' + cls + '">' + msg + '</div>'
    + '<div class="info">'
    + '<div class="row"><span class="k">📌 书源名称</span><span class="v">' + ((S && S.bookSourceName) || '') + '</span></div>'
    + '<div class="row"><span class="k">🏷 所属分组</span><span class="v">' + ((S && S.bookSourceGroup) || '') + '</span></div>'
    + '<div class="row"><span class="k">📅 当前版本</span><span class="v">v' + lv + '</span></div>'
    + '<div class="row"><span class="k">✨ 最新版本</span><span class="v">' + (latest ? ('v' + latest) : '—') + '</span></div>'
    + '</div>'
    + '<div class="log"><div class="t">📋 更新日志</div><div class="c">' + logText + '</div>'
    + (histHtml ? ('<div class="hist"><div class="t" style="font-size:12px">历史记录</div>' + histHtml + '</div>') : '')
    + '</div>'
    + '<button class="big" onclick="doUpdate()">📥 一键更新到「阅读」</button>'
    + '<div class="tip">点击后自动唤起「阅读」App 导入最新书源（legado://import/bookSource）</div>'
    + '</div><script>var SRC=' + JSON.stringify(srcUrl)
    + ';function doUpdate(){location.href="legado://import/bookSource?src="+encodeURIComponent(SRC);}</script>'
    + '</body></html>';

  try { J.startBrowserAwait('data:text/html;base64,' + J.base64Encode(html), '书源更新', false); }
  catch (e3) { try { J.toast('\n打开更新面板失败：' + e3); } catch (e4) {} }
}
